window.VO = [{"id":"n01","text":"You're his only alibi.","at":0.24,"t0":0.12,"t1":1.39},{"id":"f00","text":"Tell them I was with you!","at":3.18,"t0":1.59,"t1":3.08},{"id":"n02","text":"Your best friend's locked up for robbing a watch shop.","at":6.66,"t0":3.33,"t1":6.14},{"id":"o01","text":"Last Tuesday, seven forty. Where were you?","at":12.78,"t0":6.39,"t1":9.31},{"id":"n03","text":"The police have one blurry photo. He has you. What did you eat? Check your photos. Nobody photographs a Tuesday.","at":19.22,"t0":9.61,"t1":16.39},{"id":"f01","text":"The stall. It was raining, you had ginger chai, you paid cash, twenty rupees. Remember?","at":34.48,"t0":17.24,"t1":22.76},{"id":"o02","text":"The chaiwala remembers nothing. So what did you drink?","at":46.22,"t0":23.11,"t1":26.6},{"id":"o03","text":"How much did you pay?","at":55.9,"t0":27.95,"t1":29.62},{"id":"o04","text":"He told us ginger chai, twenty rupees.","at":61.64,"t0":30.82,"t1":33.795},{"id":"n04","text":"One more. What did he drink?","at":68.29,"t0":34.145,"t1":35.74},{"id":"n05","text":"He never said.","at":74.08,"t0":37.04,"t1":38.065},{"id":"n06","text":"Not one word about his evening, because he wasn't with you.","at":76.83,"t0":38.415,"t1":41.46},{"id":"n07","text":"He was here.","at":83.72,"t0":41.86,"t1":42.685},{"id":"o05","text":"The alibi holds. He can go.","at":88.17,"t0":44.085,"t1":46.665},{"id":"n08","text":"Nothing happened, so you had no Tuesday. Now you've got the one he wrote.","at":94.53,"t0":47.265,"t1":51.115},{"id":"n09","text":"He didn't need you to remember. He needed you not to.","at":103.03,"t0":51.515,"t1":54.29},{"id":"f02","text":"Thanks, yaar. Next time, I'll pay.","at":109.98,"t0":54.99,"t1":57.17},{"id":"n10","text":"Lie researchers call that an unanticipated question.","at":115.44,"t0":57.72,"t1":60.67},{"id":"n11","text":"So ask your best friend one. Where were they last Tuesday at seven forty?","at":121.94,"t0":60.97,"t1":64.965},{"id":"n12","text":"But first: what's on his wrist?","at":134.53,"t0":67.265,"t1":68.985}];
